begin;
select plan(19);
select has_table('public','schools','schools table exists');
select has_table('public','students','student roster exists');
select has_table('public','marks','marks table exists');
select has_table('public','memberships','server-controlled memberships exist');
select ok((select relrowsecurity from pg_class where oid='public.students'::regclass),'student RLS is enabled');
select ok((select relrowsecurity from pg_class where oid='public.marks'::regclass),'marks RLS is enabled');
select ok((select relrowsecurity from pg_class where oid='public.memberships'::regclass),'membership RLS is enabled');
select ok(exists(select 1 from pg_constraint where conrelid='public.marks'::regclass and contype='u' and pg_get_constraintdef(oid) like '%exam_id, student_id%'),'a mark per student per exam is unique');
select ok(exists(select 1 from pg_constraint where conrelid='public.teacher_subjects'::regclass and pg_get_constraintdef(oid) like '%subject_id, school_id%'),'teacher subject references remain tenant-bound');
select ok(exists(select 1 from pg_constraint where conrelid='public.exams'::regclass and pg_get_constraintdef(oid) like '%subject_id, school_id%'),'exam subject references remain tenant-bound');
select ok(exists(select 1 from pg_trigger where tgrelid='public.marks'::regclass and tgname='enforce_mark_write_before'),'server validates direct mark writes');
select ok(exists(select 1 from pg_trigger where tgrelid='public.student_notes'::regclass and tgname='guard_note_write_before'),'server validates note mutations');
select ok(not has_function_privilege('authenticated','public.provision_initial_admin(uuid,text,text)','execute'),'authenticated clients cannot provision initial admin');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='classes' and policyname='classes assigned read' and qual like '%is_assigned_teacher%'),'teacher class reads require an assignment');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='teachers' and policyname='teachers self or admin read' and qual like '%is_school_admin%'),'teacher directory is limited to self or administrators');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='teacher_subjects' and policyname='teacher subjects assigned read' and qual like '%is_assigned_teacher%'),'teacher-subject mappings are assignment-scoped');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='student_subjects' and policyname='student subjects assigned read' and qual like '%is_assigned_teacher%'),'student subject enrollment reads require an assignment');
select ok(exists(select 1 from pg_policies where schemaname='public' and tablename='timetable_slots' and policyname='timetable assigned read' and qual like '%is_assigned_teacher%'),'timetable reads require an assignment');
select ok(exists(select 1 from pg_trigger where tgrelid='public.marks'::regclass and tgname='enforce_mark_student_class_before'),'marks are bound to the examination class');
select * from finish();
rollback;
